  xm16 Vncas Vncas N012 0 sky130_fd_pr__nfet_01v8 w={W_xm16} l={L_xm16}
  xm17 N012 Vbias3 P001 0 sky130_fd_pr__nfet_01v8 w={W_xm17} l={L_xm17}
  xm18 P001 N012 0 0 sky130_fd_pr__nfet_01v8 w={W_xm18} l={L_xm18}
.ends SUB_1
* --- END DUT NETLIST ---

.control
* 1. AC Analysis
ac dec 100 1 1G
let gain_db = vdb(Ad)
let phase_deg = 180/PI * cph(v(Ad))

* Measure DC Gain
meas ac dc_gain_db find gain_db at=10

* Measure Unity Gain Frequency
meas ac unity_gain_freq when gain_db=0 fall=1

* Measure Phase Margin
meas ac phase_at_ugf find phase_deg when gain_db=0 fall=1
let phase_margin = 180 + phase_at_ugf
print phase_margin

* Measure Gain Margin
meas ac freq_at_180 when phase_deg=-180 fall=1
meas ac gain_at_180 find gain_db when phase_deg=-180 fall=1
let gain_margin = -gain_at_180
print gain_margin

* 2. Transient Analysis for Slew Rate
* The 10uF cap holds vm1 at 0.9V. A step on vp1 causes open-loop slewing.
tran 1n 2u
meas tran t1 when v(Ad)=1.0 rise=1
meas tran t2 when v(Ad)=1.3 rise=1
let slew_rate_V_us = 0.3 / (t2 - t1) / 1e6
print slew_rate_V_us

quit
.endc

